targets.query:
from(bucket: "edge-data")
  |> range(start: -5m)
  |> filter(fn: (r) => r._measurement == "device_metrics" and r._field == "cpu_percent")
  |> filter(fn: (r) => r.camera_id == "${camera_id}")
  |> last()
  |> map(fn: (r) => ({
      r with _value: if uint(v: now()) - uint(v: r._time) < uint(v: 120000000000) then 1.0 else 0.0
    }))
  |> yield(name: "status")
